mapper.insert:
insert into risk_assess_rule()
select #{dimension},#{subItem},#{level},#{operator},#{threshold},#{thresholdText},#{minAbsolute},
       #{enabled},#{description},#{suggestion},0,now()
from dual
where not exists (
    select 1 from (select * from risk_assess_rule) t
    where t.dimension = #{dimension}
      and t.sub_item <=> #{subItem}
      and t.level = #{level}
)
